    fn serve_selected(
        self,
        text_ui: Option<(&Path, OwnedFd)>,
        ready: impl FnOnce() -> io::Result<()>,
    ) -> io::Result<()> {
        let Self {
            config,
            registration,
            owner_pidfd,
            service,
            root_admin,
            learning,
