                Some(admin) => admin.run(&service, &config, &registration, &owner_pidfd, serve),
                None => serve(),
            }
        } else {
            let serve = || {
                learning::serve_optional(
                    learning.as_ref(),
                    &service,
                    &config,
                    &registration,
                    &owner_pidfd,
                    || {
                        listeners::serve_lanes_with_ready(
                            &service,
                            &config,
                            &registration,
                            &owner_pidfd,
                            || {
                                ready()?;
                                if let Some(admin) = &root_admin {
                                    admin.activate()?;
                                }
                                Ok(())
                            },
                        )
                    },
                )
            };
            match &root_admin {
                Some(admin) => admin.run(&service, &config, &registration, &owner_pidfd, serve),
                None => serve(),
            }
        }
    }
